using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Security.AccessControl;
using System.Security.Cryptography;
using System.Security.Principal;
using System.Text;

// 이 kernel은 journal 고정 namespace만 다룬다. 일반 파일/키 IPC로 노출하지 않는다.
internal abstract class NativePreparationJournalKernel {
 internal abstract string Sid{get;}internal abstract string RootIdentity{get;}
 internal abstract void Check();internal abstract void OpenNamespace();
 internal abstract string[] Names();internal abstract long UsedBytes();internal abstract byte[] Read(string name);
 internal abstract void Acquire();internal abstract void Create(string name,byte[] bytes);internal abstract void Settle();internal abstract void Release();
 internal abstract byte[] Protect(byte[] bytes);internal abstract byte[] Unprotect(byte[] bytes);
 internal abstract void Abandon();
}

internal sealed class WindowsNativePreparationJournalKernel:NativePreparationJournalKernel {
 const long Maximum=67108864;const string Issue="native-journal.v1.issued",Lock="native-journal.v1.lock";
 readonly DesktopTrustKeyRootSource root;readonly Action current;readonly string directory;FileStream held;string lockHash,lockToken;long lockSequence;bool opened,unknown,issuing;
 [StructLayout(LayoutKind.Sequential)]struct FT{internal uint Low,High;}
 [StructLayout(LayoutKind.Sequential)]struct FI{internal uint Attributes;internal FT Created,Accessed,Written;internal uint Volume,SizeHigh,SizeLow,Links,IndexHigh,IndexLow;}
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetFileInformationByHandle(IntPtr handle,out FI info);
 static readonly byte[] Entropy=Encoding.UTF8.GetBytes("Anvil.NativePreparationJournal.v1");
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr CreateFileW(string path,uint access,uint share,IntPtr security,uint disposition,uint flags,IntPtr template);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool FlushFileBuffers(IntPtr handle);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool CloseHandle(IntPtr handle);
 internal WindowsNativePreparationJournalKernel(DesktopTrustKeyRootSource owner,Action check){root=owner;current=check;directory=Path.Combine(root.PathValue,"native-journal.v1");}
 // 최종 CLOSED flush/응답 불명과 확정 해제를 새 host가 구별할 OS 근거가 없다.
 // label/주입 bool로 승격하지 않는다. 아래 저장 알고리즘은 현재 실제 공급자로 활성화되지 않는다.
 static void RequireDurabilitySupport(){throw new InvalidOperationException("NATIVE_JOURNAL_DURABILITY_UNSUPPORTED");}
 internal override string Sid{get{Check();return root.UserSid;}}internal override string RootIdentity{get{Check();return root.Identity;}}
 static Exception Invalid(){return new DesktopTrustKeyStoreUnknownException();}
 internal override void Check(){if(unknown)throw Invalid();current();root.Check();if(opened)root.CheckJournalNamespace();}
 string PathFor(string name){if(name==Issue||name==Lock)return Path.Combine(root.PathValue,name);if(!System.Text.RegularExpressions.Regex.IsMatch(name,@"\A(?:exists|row)\.[a-f0-9]{64}\.[12]\z"))throw Invalid();return Path.Combine(directory,name);}
 static void Clear(byte[] bytes){if(bytes!=null)Array.Clear(bytes,0,bytes.Length);}
 void Shape(string path){var f=new FileInfo(path);if(!f.Exists||(f.Attributes&(FileAttributes.ReparsePoint|FileAttributes.Directory))!=0||f.Length<1||f.Length>Maximum)throw Invalid();var security=f.GetAccessControl(AccessControlSections.Owner|AccessControlSections.Access);if(security.GetOwner(typeof(SecurityIdentifier)).Value!=root.UserSid)throw Invalid();var rules=security.GetAccessRules(true,true,typeof(SecurityIdentifier));if(rules.Count!=2)throw Invalid();foreach(FileSystemAccessRule r in rules)if(r.AccessControlType!=AccessControlType.Allow||(r.IdentityReference.Value!=root.UserSid&&r.IdentityReference.Value!="S-1-5-18")||r.FileSystemRights!=FileSystemRights.FullControl)throw Invalid();}
 string Identity(FileStream stream){FI info;if(!GetFileInformationByHandle(stream.SafeFileHandle.DangerousGetHandle(),out info)||info.Links!=1||(info.Attributes&0x410)!=0)throw Invalid();return String.Join(":",info.Volume,info.IndexHigh,info.IndexLow);}
 void AssertIdentity(FileStream stream,string path){Shape(path);string original=Identity(stream);using(var other=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){if(Identity(other)!=original)throw Invalid();}Shape(path);Check();}
 internal override byte[] Read(string name){Check();string path=PathFor(name);if(!File.Exists(path))return null;Shape(path);byte[] bytes;using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){AssertIdentity(stream,path);if(stream.Length>Maximum)throw Invalid();bytes=new byte[(int)stream.Length];int at=0,n;while(at<bytes.Length&&(n=stream.Read(bytes,at,bytes.Length-at))>0)at+=n;if(at!=bytes.Length||stream.ReadByte()!=-1)throw Invalid();AssertIdentity(stream,path);}Check();return bytes;}
 internal override string[] Names(){Check();if(!opened)throw Invalid();var names=Directory.GetFileSystemEntries(directory).Select(Path.GetFileName).ToArray();foreach(string name in names){PathFor(name);Shape(PathFor(name));}Check();return names;}
 internal override long UsedBytes(){Check();long n=0;foreach(string name in Names().Concat(new[]{Issue,Lock})){string path=PathFor(name);if(File.Exists(path)){Shape(path);n=checked(n+new FileInfo(path).Length);}}Check();return n;}
 // 삭제하지 않는 고정 lock: OS 배타 handle과 정착된 ACTIVE/CLOSED 원 체인을 함께 검산한다.
 void ReadLock(){AssertIdentity(held,PathFor(Lock));held.Position=0;if(held.Length>Maximum)throw Invalid();byte[] bytes=new byte[(int)held.Length];try{int at=0,n;while(at<bytes.Length&&(n=held.Read(bytes,at,bytes.Length-at))>0)at+=n;if(at!=bytes.Length)throw Invalid();string text=new UTF8Encoding(false,true).GetString(bytes);if(text.Length==0){if(!issuing)throw Invalid();lockSequence=0;lockHash=null;return;}if(!text.EndsWith("\n",StringComparison.Ordinal))throw Invalid();string previous=null,token=null,state=null;long sequence=0;foreach(string line in text.Substring(0,text.Length-1).Split('\n')){byte[] cipher=Convert.FromBase64String(line),plain=null;try{plain=Unprotect(cipher);var row=DesktopTrustKeyHostSource.Parse(plain,false);DesktopTrustKeyHostSource.Exact(row,"schemaVersion,purpose,rootIdentity,sid,sequence,previousHash,token,state");if(DesktopTrustKeyHostSource.Positive(row["schemaVersion"])!=1||DesktopTrustKeyHostSource.Text(row,"purpose")!="NATIVE_JOURNAL_LOCK"||DesktopTrustKeyHostSource.Text(row,"rootIdentity")!=root.Identity||DesktopTrustKeyHostSource.Text(row,"sid")!=root.UserSid||DesktopTrustKeyHostSource.Positive(row["sequence"])!=++sequence||!Object.Equals(row["previousHash"],previous))throw Invalid();string next=DesktopTrustKeyHostSource.Text(row,"state"),nextToken=DesktopTrustKeyHostSource.Id(row,"token");if((sequence%2==1&&next!="ACTIVE")||(sequence%2==0&&(next!="CLOSED"||nextToken!=token)))throw Invalid();state=next;token=nextToken;previous=DesktopTrustKeyHostSource.Hash(plain);}finally{Clear(cipher);Clear(plain);}}if(state!="CLOSED")throw Invalid();lockSequence=sequence;lockHash=previous;}finally{Clear(bytes);}AssertIdentity(held,PathFor(Lock));}
 void AppendLock(string state){AssertIdentity(held,PathFor(Lock));var row=new Dictionary<string,object>{{"schemaVersion",1},{"purpose","NATIVE_JOURNAL_LOCK"},{"rootIdentity",root.Identity},{"sid",root.UserSid},{"sequence",lockSequence+1},{"previousHash",lockHash},{"token",lockToken},{"state",state}};byte[] plain=Encoding.UTF8.GetBytes(DesktopTrustKeyHostSource.Canonical(row,0)),cipher=null,bytes=null;try{cipher=Protect(plain);bytes=Encoding.ASCII.GetBytes(Convert.ToBase64String(cipher)+"\n");long total=opened?UsedBytes():held.Length;if(checked(total+bytes.Length+8192)>Maximum)throw Invalid();long start=held.Length;held.Position=start;held.Write(bytes,0,bytes.Length);held.Flush(true);held.Position=start;for(int i=0;i<bytes.Length;i++)if(held.ReadByte()!=bytes[i])throw Invalid();if(held.Length!=start+bytes.Length)throw Invalid();AssertIdentity(held,PathFor(Lock));lockSequence++;lockHash=DesktopTrustKeyHostSource.Hash(plain);}finally{Clear(plain);Clear(cipher);Clear(bytes);}}
 internal override void Acquire(){RequireDurabilitySupport();Check();if(held!=null)throw Invalid();try{held=new FileStream(PathFor(Lock),issuing?FileMode.CreateNew:FileMode.Open,FileAccess.ReadWrite,FileShare.Read);ReadLock();lockToken=Guid.NewGuid().ToString("D");AppendLock("ACTIVE");if(issuing)FlushDirectory(root.PathValue);Check();}catch{unknown=true;throw Invalid();}}
 internal override void Create(string name,byte[] bytes){Check();if(held==null||bytes==null||bytes.Length<1||bytes.Length>Maximum)throw Invalid();using(var f=new FileStream(PathFor(name),FileMode.CreateNew,FileAccess.ReadWrite,FileShare.Read)){Identity(f);f.Write(bytes,0,bytes.Length);f.Flush(true);AssertIdentity(f,PathFor(name));if(f.Length!=bytes.Length)throw Invalid();f.Position=0;for(int i=0;i<bytes.Length;i++)if(f.ReadByte()!=bytes[i])throw Invalid();AssertIdentity(f,PathFor(name));}Check();byte[] back=Read(name);try{if(back==null||!back.SequenceEqual(bytes))throw Invalid();}finally{Clear(back);}}
 void FlushDirectory(string path){Check();IntPtr handle=CreateFileW(path,0x40000000,7,IntPtr.Zero,3,0x02200000,IntPtr.Zero);if(handle==IntPtr.Zero||handle==new IntPtr(-1))throw new InvalidOperationException("NATIVE_JOURNAL_METADATA_UNSUPPORTED");try{if(!FlushFileBuffers(handle))throw new InvalidOperationException("NATIVE_JOURNAL_METADATA_UNSUPPORTED");}finally{if(!CloseHandle(handle))unknown=true;}Check();}
 internal override void Settle(){Check();if(held==null)throw Invalid();if(opened)FlushDirectory(directory);FlushDirectory(root.PathValue);Check();}
 internal override void Release(){Check();if(held==null)throw Invalid();try{AssertIdentity(held,PathFor(Lock));AppendLock("CLOSED");held.Dispose();held=null;}catch{unknown=true;throw Invalid();}}
 internal override byte[] Protect(byte[] bytes){Check();return ProtectedData.Protect(bytes,Entropy,DataProtectionScope.CurrentUser);}
 internal override byte[] Unprotect(byte[] bytes){Check();return ProtectedData.Unprotect(bytes,Entropy,DataProtectionScope.CurrentUser);}
 internal override void Abandon(){unknown=true;if(held!=null){held.Dispose();held=null;}/* 불명 lock은 삭제하지 않는다. */}
 internal override void OpenNamespace(){RequireDurabilitySupport();Check();byte[] cipher=Read(Issue),plain=null;if(cipher==null)throw Invalid();try{plain=Unprotect(cipher);var issue=DesktopTrustKeyHostSource.Parse(plain,false);DesktopTrustKeyHostSource.Exact(issue,"schemaVersion,purpose,sid,rootIdentity,namespaceIdentity,issuanceId");if(DesktopTrustKeyHostSource.Positive(issue["schemaVersion"])!=1||DesktopTrustKeyHostSource.Text(issue,"purpose")!="NATIVE_JOURNAL_ISSUANCE"||DesktopTrustKeyHostSource.Text(issue,"sid")!=root.UserSid||DesktopTrustKeyHostSource.Text(issue,"rootIdentity")!=root.Identity)throw Invalid();DesktopTrustKeyHostSource.Id(issue,"issuanceId");root.RetainJournalNamespace(false);opened=true;if(DesktopTrustKeyHostSource.Text(issue,"namespaceIdentity")!=root.JournalIdentity)throw Invalid();Check();}finally{Clear(cipher);Clear(plain);}}
 // 원 root 생산자의 실제 exclusive 생성 capability를 한 번만 소비한다. 기존 root 부재를 발급으로 승격하지 않는다.
 internal static void IssueFreshRoot(DesktopTrustKeyRootSource root,Action check){object permit=root.TakeJournalCreationPermit();if(permit==null)return;var kernel=new WindowsNativePreparationJournalKernel(root,check);byte[] plain=null,cipher=null;try{root.ConsumeJournalCreationPermit(permit);kernel.issuing=true;kernel.Acquire();root.RetainJournalNamespace(true);kernel.opened=true;var issue=new Dictionary<string,object>{{"schemaVersion",1},{"purpose","NATIVE_JOURNAL_ISSUANCE"},{"sid",root.UserSid},{"rootIdentity",root.Identity},{"namespaceIdentity",root.JournalIdentity},{"issuanceId",Guid.NewGuid().ToString("D")}};plain=Encoding.UTF8.GetBytes(DesktopTrustKeyHostSource.Canonical(issue,0));cipher=kernel.Protect(plain);kernel.Create(Issue,cipher);kernel.Settle();kernel.Release();}catch{kernel.Abandon();/* 기존 binding 기능을 바꾸지 않는다. journal은 불완전 발급/ACTIVE를 거절한다. */}finally{Clear(plain);Clear(cipher);}}
}
